try {
    const hasEui = p => p && typeof p === 'object' && (p.deveui || p.devEUI || p.eui);
    let p = hasEui(msg) ? msg : msg.payload;
    if (Buffer.isBuffer(p)) p = p.toString('utf8');
    if (typeof p === 'string') p = JSON.parse(p);
    if (!p || typeof p !== 'object' || Array.isArray(p)) throw Error('Uplink JSON invalido');
    const eui = String(p.deveui || p.devEUI || p.eui || '').trim().toLowerCase();
    if (!/^[0-9a-f]{16}$/.test(eui)) throw Error('DevEUI invalido');
    let decoded = p.object;
    if (typeof decoded === 'string') decoded = JSON.parse(decoded);
    if (!decoded || typeof decoded !== 'object' || Array.isArray(decoded)) {
      throw Error('Falta object decodificado: asignar codec en LNS; no se interpreta el payload binario');
    }
    const values = {};
    Object.keys(decoded).forEach(k => {
      if (['__proto__','constructor','prototype'].includes(k)) return;
      const v = decoded[k];
      if (typeof v === 'string' || typeof v === 'boolean' || (typeof v === 'number' && Number.isFinite(v))) values[k] = v;
      // Preserve compound values as JSON text without guessing flattening rules.
      else if (v !== null && typeof v === 'object') values[k] = JSON.stringify(v);
    });
    if (!Object.keys(values).length) throw Error('object no contiene valores publicables');
    const rx = Array.isArray(p.rxInfo) ? (p.rxInfo[0] || {}) : {};
    const tx = p.txInfo || {};
    const dr = p.dr || tx.dataRate || {};
    const first = (...items) => items.find(x => x !== undefined && x !== null);
    const metadata = {rssi:first(p.rssi,rx.rssi),snr:first(p.snr,rx.loRaSNR),
      frame_count:first(p.fcnt,p.fCnt,p.frameCount),fport:first(p.fport,p.fPort,p.port),
      frequency:first(p.freq,p.frequency,tx.frequency),
      spreading_factor:dr.spreadFactor,bandwidth_khz:dr.bandwidth};
    // Codec keys take precedence; radio metadata never overwrites sensor data.
    Object.keys(metadata).forEach(k => {
      if (!Object.prototype.hasOwnProperty.call(values,k) && typeof metadata[k] === 'number' && Number.isFinite(metadata[k])) values[k] = metadata[k];
    });
    const time = first(p.time,rx.time);
    let ts = typeof time === 'string' ? Date.parse(time) : NaN;
    const source = !Number.isFinite(ts) || ts > Date.now()+300000 ? 'node_red' : 'gateway';
    if (source === 'node_red') ts = Date.now();
    if (!Object.prototype.hasOwnProperty.call(values,'timestamp_source')) values.timestamp_source = source;
    const seen = flow.get('uplink_devices') || [];
    if (!seen.includes(eui)) {seen.push(eui);flow.set('uplink_devices',seen);}
    const connect = {topic:'v1/gateway/connect',payload:{device:eui},qos:'1',retain:false};
    const telemetry = {topic:'v1/gateway/telemetry',payload:{[eui]:[{ts,values}]},qos:'1',retain:false};
    return [[connect,telemetry]];
  } catch (err) {node.error(err.message,msg);return null;}

const lt = String(env.get('LT_DEVEUI') || '').toLowerCase();
  if (msg.topic !== 'v1/gateway/telemetry' || !msg.payload || !Array.isArray(msg.payload[lt])) return msg;
  msg.payload[lt].forEach(sample => {
    const values = sample.values;
    ['RO1','RO2'].forEach(k => {
      if (values[k+'_status'] === 'ON') values[k.toLowerCase()+'_active'] = true;
      if (values[k+'_status'] === 'OFF') values[k.toLowerCase()+'_active'] = false;
    });
    ['DO1','DO2'].forEach(k => {
      if (values[k+'_status'] === 'L') values[k.toLowerCase()+'_active'] = true;
      if (values[k+'_status'] === 'H') values[k.toLowerCase()+'_active'] = false;
    });
    // Do not refresh the control cache on frames that contain no output states.
    if (!['ro1_active','ro2_active','do1_active','do2_active'].some(k => typeof values[k] === 'boolean')) return;
    const old = flow.get('lt_state');
    if (!old || sample.ts >= old.ts) flow.set('lt_state',{ts:sample.ts,values:{...values}});
  });
  return msg;

const ids = [...new Set([...(flow.get('uplink_devices') || []),env.get('LT_DEVEUI'),env.get('AM_DEVEUI')]
    .map(x => String(x || '').toLowerCase()).filter(x => /^[0-9a-f]{16}$/.test(x)))];
  return ids.length ? [ids.map(device => ({topic:'v1/gateway/connect',payload:{device},qos:'1',retain:false}))] : null;

let p;
  try {
    p = msg.payload;
    if (Buffer.isBuffer(p)) p = p.toString('utf8');
    if (typeof p === 'string') p = JSON.parse(p);
    // A gateway RPC reply has a top-level id and no data.method. Ignore echoes.
    if (!p || !p.data || typeof p.data.method !== 'string') return null;
  } catch (err) {node.error('RPC JSON invalido', msg); return null;}
  const id = p.data.id;
  if (!Number.isInteger(id) || typeof p.device !== 'string') {node.error('RPC sin id numerico o device', msg); return null;}
  const reply = data => ({topic:'v1/gateway/rpc',payload:{device:p.device,id,data},qos:'1',retain:false});
  const fail = error => [null,reply({accepted:false,error}),null];
  const lt = String(env.get('LT_DEVEUI') || '').toLowerCase();
  if (p.device !== lt) return fail('Solo se controla el LT22222 registrado; usar DevEUI en minusculas');
  const match = /^(get|set)(RO1|RO2|DO1|DO2)$/.exec(p.data.method);
  if (!match) return fail('Metodo permitido: get/setRO1, RO2, DO1 o DO2');
  const output = match[2];
  if (match[1] === 'get') {
    const cached = flow.get('lt_state');
    const maxAge = Number(env.get('STATE_MAX_AGE_S') || 900)*1000;
    const key = output.toLowerCase()+'_active';
    if (!cached || Date.now()-cached.ts > maxAge || typeof cached.values[key] !== 'boolean') return fail('Estado ausente o antiguo: esperar uplink reciente');
    return [null,reply(cached.values[key]),null];
  }
  const val = p.data.params;
  if (![true,false,0,1].includes(val)) return fail('params debe ser booleano true/false o numero 0/1');
  const active = val === true || val === 1;
  const now = Date.now();
  const cache = flow.get('rpc_seen') || {};
  Object.keys(cache).forEach(k => {if (now-cache[k].ts > 120000) delete cache[k];});
  const key = p.device+':'+id;
  const signature = JSON.stringify([p.data.method,active]);
  if (cache[key]) {
    if (cache[key].signature !== signature) return fail('ID RPC reutilizado con otro comando');
    return [null,reply(cache[key].result),null];
  }
  const bytes = output.startsWith('RO') ? [0x03,0x11,0x11] : [0x02,0x11,0x11,0x11];
  bytes[Number(output.slice(-1))] = active ? 0x01 : 0x00;
  const port = Number(env.get('LT_DOWNLINK_FPORT') || 2);
  if (!Number.isInteger(port) || port < 1 || port > 223) return fail('FPort invalido');
  const app = String(env.get('LNS_DOWNLINK_APP_ID') || '').trim();
  if (!/^\d+$/.test(app)) return fail('LNS_DOWNLINK_APP_ID debe ser numerico');
  const packet = {topic:'application/'+app+'/device/'+lt+'/tx',
    payload:{confirmed:false,fport:port,data:Buffer.from(bytes).toString('base64')},
    qos:'0',retain:false,command_key:output+':'+(active ? '1' : '0')};
  const diagnostic = {payload:{output,active,hex:Buffer.from(bytes).toString('hex'),
    base64:Buffer.from(bytes).toString('base64'),eui:lt,port,topic:packet.topic,command_key:packet.command_key}};
  const enabled = String(env.get('ENABLE_DOWNLINK')).toLowerCase() === 'true';
  if (!enabled) return [null,reply({accepted:false,stage:'simulation',hex:diagnostic.payload.hex}),diagnostic];
  const last = flow.get('last_command_ms') || 0;
  if (now-last < 2000) return fail('Esperar al menos 2 segundos entre comandos');
  flow.set('last_command_ms',now);
  const result = {accepted:true,stage:'submitted_to_mqtt_node',executed:false,output,requested:active};
  cache[key] = {ts:now,signature,result}; flow.set('rpc_seen',cache);
  // This reply confirms preparation only. Actual state arrives as telemetry.
  return [packet,reply(result),diagnostic];
